from pathlib import Path
p=Path('/mnt/data/bh_story_projeto/index.html')
s=p.read_text()
s=s.replace('<div class="head-actions"><a href="#"><i>♙</i>Minha conta</a><a href="#"><i>♡</i>Favoritos</a><a href="#catalogo"><i>🛒</i>Carrinho <b id="cartCount">0</b></a></div>', '<div class="head-actions"><a href="#" onclick="openAccount();return false"><i>♙</i>Minha conta</a><a href="#"><i>♡</i>Favoritos</a><a href="#catalogo"><i>🛒</i>Carrinho <b id="cartCount">0</b></a></div>')
s=s.replace('<button class="admin-link" onclick="openAdmin()">Área administrativa</button>\n<div class="modal" id="modal"><div class="dialog" id="dialog"></div></div>', '<button class="admin-link" onclick="openAdmin()">Área administrativa</button>\n<button class="chat-launch" onclick="toggleChat()">💬 Falar com Monica</button>\n<div class="modal" id="modal"><div class="dialog" id="dialog"></div></div>\n<div class="chatbox" id="chatbox"><div class="chathead"><b>Monica — Atendente IA</b><button onclick="toggleChat()">×</button></div><div id="chatlog" class="chatlog"><div class="bubble bot">Olá! Eu sou a Monica, atendente virtual da BH Story. 💜 Como posso ajudar?</div></div><form class="chatform" onsubmit="sendMonica(event)"><input id="chatinput" placeholder="Digite sua mensagem..." autocomplete="off" required><button class="btn">Enviar</button></form></div>')
# add styles before closing style
css='''
.chat-launch{position:fixed;right:18px;bottom:18px;z-index:8;background:linear-gradient(110deg,#7100e8,#9e20ff);color:#fff;padding:13px 18px;border-radius:28px;font-weight:800;box-shadow:0 8px 30px #7100e866}.chatbox{display:none;position:fixed;right:18px;bottom:78px;width:min(360px,calc(100vw - 28px));height:440px;max-height:70vh;z-index:12;background:#111018;border:1px solid #66318d;border-radius:16px;overflow:hidden;box-shadow:0 20px 70px #000}.chatbox.open{display:flex;flex-direction:column}.chathead{padding:14px;background:#231033;display:flex;justify-content:space-between;align-items:center}.chathead button{background:none;color:white;font-size:24px}.chatlog{padding:14px;overflow:auto;flex:1;display:flex;flex-direction:column;gap:10px}.bubble{padding:10px 12px;border-radius:12px;max-width:88%;font-size:13px;line-height:1.5}.bubble.bot{background:#282331;align-self:flex-start}.bubble.user{background:#6e13cb;align-self:flex-end}.chatform{display:flex;padding:10px;gap:7px;border-top:1px solid #38313f}.chatform input{min-width:0;flex:1;background:#211e29;color:#fff;border:1px solid #393342;border-radius:9px;padding:10px}.chatform .btn{padding:9px 12px}.field input{width:100%;background:#211e29;color:#fff;border:1px solid #393342;border-radius:9px;padding:11px}.admin-stats{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0}.stat{background:#211a2b;padding:13px;border-radius:10px}.stat strong{display:block;font-size:23px;color:#b65aff}.admin-table{width:100%;border-collapse:collapse;font-size:12px}.admin-table td,.admin-table th{padding:9px 6px;border-bottom:1px solid #38313f;text-align:left;vertical-align:top}.admin-section{margin-top:18px}.status-online{color:#67e59a;font-weight:700}.notice.info{background:#1d2030;border-color:#3e4770;color:#d9ddff}
'''
s=s.replace('</style>',css+'</style>')
start=s.index('<script>')
end=s.index('</script>',start)+len('</script>')
script=r'''<script>
let products=JSON.parse(localStorage.getItem('bh_products')||'[]');let cart={};let quantities={};let currentUser=null;let adminEvents=null;
const money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const api=async(url,options={})=>{const r=await fetch(url,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});let d={};try{d=await r.json()}catch{}if(!r.ok)throw new Error(d.error||'Ocorreu um erro.');return d};
function save(){localStorage.setItem('bh_products',JSON.stringify(products));}
function esc(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function renderProducts(){const q=(document.getElementById('search').value||'').toLowerCase();const list=products.map((p,i)=>({...p,i})).filter(p=>p.name.toLowerCase().includes(q));document.getElementById('productCount').textContent=products.length+' produto(s)';document.getElementById('products').innerHTML=list.length?list.map(p=>`<article class="product"><div class="photo"><span class="tag">${esc(p.tag||'💜 Lançamento')}</span>${p.image?`<img src="${p.image}" alt="">`:'Imagem do produto'}</div><div class="details"><div class="name">${esc(p.name)}</div><div class="price">${money(p.price)}</div><div class="old">${p.old?money(p.old):'&nbsp;'}</div><div class="buyrow"><div class="qty"><button onclick="changeQty(${p.i},-1)">−</button><span id="q${p.i}">${quantities[p.i]||1}</span><button onclick="changeQty(${p.i},1)">+</button></div><button class="btn add" onclick="addCart(${p.i})">Adicionar</button></div><div class="muted" style="font-size:11px;margin-top:6px">${p.stock>0?'Disponíveis: '+p.stock:'Consulte disponibilidade'}</div></div></article>`).join(''):'<div class="empty" style="grid-column:1/-1">Ainda não há produtos cadastrados. Volte em breve! 💜</div>';}
function changeQty(i,d){quantities[i]=Math.max(1,Math.min(Number(products[i].stock||99),Number(quantities[i]||1)+d));document.getElementById('q'+i).textContent=quantities[i];}
function addCart(i){let n=Number(quantities[i]||1),stock=Number(products[i].stock||99);cart[i]=Math.min(stock,(cart[i]||0)+n);renderCart();}
function renderCart(){let entries=Object.keys(cart).filter(k=>cart[k]>0);document.getElementById('cartCount').textContent=entries.reduce((a,k)=>a+cart[k],0);document.getElementById('cartItems').className=entries.length?'':'empty';document.getElementById('cartItems').innerHTML=entries.length?entries.map(k=>`<div class="cart-item"><span>${esc(products[k].name)} × ${cart[k]}</span><b>${money(products[k].price*cart[k])}</b></div>`).join(''):'Seu carrinho está vazio.<br>Adicione produtos para começar.';document.getElementById('total').textContent=money(entries.reduce((a,k)=>a+products[k].price*cart[k],0));}
function showModal(){document.getElementById('modal').classList.add('show')}function closeAdmin(){document.getElementById('modal').classList.remove('show')}
document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeAdmin()});
function openAccount(){document.getElementById('dialog').innerHTML=`<h2>Minha conta BH Story</h2><div class="notice info">Entre na sua conta ou crie seu cadastro para acompanhar seus pedidos.</div><div class="formgrid"><div class="field full"><label>E-mail</label><input id="accEmail" type="email" autocomplete="email" placeholder="voce@email.com"></div><div class="field full"><label>Senha</label><input id="accPassword" type="password" autocomplete="current-password" placeholder="Mínimo de 8 caracteres"></div></div><br><button class="btn" onclick="customerLogin()">Entrar</button> <button class="btn secondary" onclick="registerForm()">Criar minha conta</button><button class="btn secondary" onclick="closeAdmin()">Fechar</button>`;showModal();}
function registerForm(){document.getElementById('dialog').innerHTML=`<h2>Criar conta</h2><p class="muted">Seus dados serão usados para cadastro e entrega dos pedidos.</p><div class="formgrid"><div class="field"><label>Nome completo *</label><input id="rName" autocomplete="name"></div><div class="field"><label>E-mail *</label><input id="rEmail" type="email" autocomplete="email"></div><div class="field full"><label>Senha (mínimo 8 caracteres) *</label><input id="rPassword" type="password" autocomplete="new-password"></div><div class="field"><label>CEP *</label><input id="rZip" autocomplete="postal-code"></div><div class="field"><label>Rua / Avenida *</label><input id="rStreet" autocomplete="street-address"></div><div class="field"><label>Número *</label><input id="rNumber"></div><div class="field"><label>Complemento</label><input id="rComplement"></div><div class="field"><label>Bairro *</label><input id="rDistrict"></div><div class="field"><label>Cidade *</label><input id="rCity" autocomplete="address-level2"></div><div class="field"><label>Estado (UF) *</label><input id="rState" maxlength="2" autocomplete="address-level1"></div></div><p class="muted" style="font-size:11px">Ao criar a conta, você confirma que os dados são seus e autoriza seu uso para cadastro e entrega. Não informe dados de terceiros sem autorização.</p><button class="btn" onclick="customerRegister()">Criar conta</button> <button class="btn secondary" onclick="openAccount()">Voltar</button>`;}
async function customerLogin(){try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({email:document.getElementById('accEmail').value,password:document.getElementById('accPassword').value})});currentUser=d.user;closeAdmin();startHeartbeat();alert('Bem-vindo(a), '+currentUser.name+'!');}catch(e){alert(e.message)}}
async function customerRegister(){try{const v=id=>document.getElementById(id).value.trim();const d=await api('/api/register',{method:'POST',body:JSON.stringify({name:v('rName'),email:v('rEmail'),password:v('rPassword'),zip:v('rZip'),street:v('rStreet'),number:v('rNumber'),complement:v('rComplement'),district:v('rDistrict'),city:v('rCity'),state:v('rState')})});currentUser=d.user;closeAdmin();startHeartbeat();alert('Cadastro realizado! Bem-vindo(a) à BH Story. 💜');}catch(e){alert(e.message)}}
function startHeartbeat(){api('/api/heartbeat',{method:'POST',body:'{}'}).catch(()=>{});setInterval(()=>api('/api/heartbeat',{method:'POST',body:'{}'}).catch(()=>{}),25000);}
async function checkout(){if(!Object.keys(cart).length)return alert('Adicione algum produto primeiro.');try{if(!currentUser){openAccount();return alert('Entre ou crie sua conta para finalizar o pedido.');}const items=Object.keys(cart).filter(k=>cart[k]>0).map(k=>({name:products[k].name,quantity:cart[k],price:products[k].price}));const d=await api('/api/orders',{method:'POST',body:JSON.stringify({items})});alert('Pedido '+d.order.id+' recebido! A equipe BH Story foi notificada. 💜');cart={};renderCart();}catch(e){alert(e.message)}}
function openAdmin(){document.getElementById('dialog').innerHTML=`<h2>Painel administrativo BH Story</h2><div class="field"><label>E-mail administrativo</label><input id="adminEmail" type="email" value="admin@bhstory.local"></div><div class="field" style="margin-top:10px"><label>Senha administrativa</label><input id="adminPass" type="password" placeholder="Senha configurada no servidor"></div><br><button class="btn" onclick="adminLogin()">Entrar no painel</button> <button class="btn secondary" onclick="closeAdmin()">Fechar</button><p class="muted" style="font-size:11px">A senha real é configurada pelo responsável no servidor, nunca neste navegador.</p>`;showModal();}
async function adminLogin(){try{await api('/api/admin/login',{method:'POST',body:JSON.stringify({email:document.getElementById('adminEmail').value,password:document.getElementById('adminPass').value})});adminPanel();}catch(e){alert(e.message)}}
async function adminPanel(){try{const d=await api('/api/admin/data');document.getElementById('dialog').innerHTML=`<h2>Painel BH Story</h2><div class="admin-stats"><div class="stat"><span class="muted">Online agora</span><strong id="onlineCount">${d.online.length}</strong></div><div class="stat"><span class="muted">Clientes cadastrados</span><strong>${d.customers.length}</strong></div><div class="stat"><span class="muted">Pedidos</span><strong>${d.orders.length}</strong></div></div><div class="notice info" id="adminNotice">Painel conectado. Novos pedidos e presença serão atualizados em tempo real enquanto esta página estiver aberta.</div><div class="admin-section"><h3>Clientes online</h3><div id="onlineList">${onlineHtml(d.online)}</div></div><div class="admin-section"><h3>Pedidos recebidos</h3><div id="ordersList">${ordersHtml(d.orders)}</div></div><div class="admin-section"><h3>Clientes cadastrados</h3><div id="customersList">${customersHtml(d.customers)}</div></div><br><button class="btn secondary" onclick="refreshAdmin()">Atualizar</button> <button class="btn secondary" onclick="adminLogout()">Sair</button>`;if(adminEvents)adminEvents.close();adminEvents=new EventSource('/api/admin/events');adminEvents.addEventListener('order',e=>{const o=JSON.parse(e.data);notifyOrder(o);refreshAdmin();});adminEvents.addEventListener('presence',()=>refreshAdmin());adminEvents.addEventListener('order-update',()=>refreshAdmin());showModal();}catch(e){alert(e.message)}}
function onlineHtml(a){return a.length?`<table class="admin-table"><tr><th>Cliente</th><th>E-mail</th><th>Status</th></tr>${a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td class="status-online">● Online</td></tr>`).join('')}</table>`:'<p class="muted">Nenhum cliente com login ativo neste momento.</p>'}
function ordersHtml(a){return a.length?`<table class="admin-table"><tr><th>Pedido / Cliente</th><th>Total</th><th>Entrega</th><th>Status</th></tr>${a.map(o=>`<tr><td><b>${esc(o.id)}</b><br>${esc(o.customerName)}<br><small>${new Date(o.createdAt).toLocaleString('pt-BR')}</small><br>${o.items.map(i=>esc(i.name)+' × '+i.quantity).join('<br>')}</td><td>${money(o.total)}</td><td>${esc(o.address.street)}, ${esc(o.address.number)}<br>${esc(o.address.district)} — ${esc(o.address.city)}/${esc(o.address.state)}<br>CEP ${esc(o.address.zip)}</td><td><select onchange="updateOrder('${o.id}',this.value)"><option ${o.status==='Recebido'?'selected':''}>Recebido</option><option ${o.status==='Em preparação'?'selected':''}>Em preparação</option><option ${o.status==='Enviado'?'selected':''}>Enviado</option><option ${o.status==='Concluído'?'selected':''}>Concluído</option><option ${o.status==='Cancelado'?'selected':''}>Cancelado</option></select><br>${esc(o.status)}</td></tr>`).join('')}</table>`:'<p class="muted">Nenhum pedido recebido ainda.</p>'}
function customersHtml(a){return a.length?`<table class="admin-table"><tr><th>Nome</th><th>E-mail</th><th>Cidade</th><th>Cadastro</th></tr>${a.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.email)}</td><td>${esc(x.address.city)}/${esc(x.address.state)}</td><td>${new Date(x.createdAt).toLocaleDateString('pt-BR')}</td></tr>`).join('')}</table>`:'<p class="muted">Nenhum cliente cadastrado.</p>'}
async function refreshAdmin(){try{const d=await api('/api/admin/data');const a=document.getElementById('onlineCount');if(a)a.textContent=d.online.length;const o=document.getElementById('onlineList');if(o)o.innerHTML=onlineHtml(d.online);const p=document.getElementById('ordersList');if(p)p.innerHTML=ordersHtml(d.orders);const c=document.getElementById('customersList');if(c)c.innerHTML=customersHtml(d.customers);}catch{}}
function notifyOrder(o){const n=document.getElementById('adminNotice');if(n)n.innerHTML=`🔔 <b>NOVO PEDIDO!</b> ${esc(o.id)} — ${esc(o.customerName)} — ${money(o.total)}`;if('Notification'in window&&Notification.permission==='granted')new Notification('Novo pedido BH Story',{body:o.id+' • '+o.customerName+' • '+money(o.total)});}
async function updateOrder(id,status){try{await api('/api/admin/order/'+id,{method:'POST',body:JSON.stringify({status})});refreshAdmin()}catch(e){alert(e.message)}}
async function adminLogout(){if(adminEvents)adminEvents.close();await api('/api/logout',{method:'POST',body:'{}'}).catch(()=>{});closeAdmin()}
function toggleChat(){document.getElementById('chatbox').classList.toggle('open')}
async function sendMonica(e){e.preventDefault();const input=document.getElementById('chatinput'),msg=input.value.trim();if(!msg)return;const log=document.getElementById('chatlog');log.insertAdjacentHTML('beforeend',`<div class="bubble user">${esc(msg)}</div>`);input.value='';try{const d=await api('/api/monica',{method:'POST',body:JSON.stringify({message:msg})});log.insertAdjacentHTML('beforeend',`<div class="bubble bot"><b>${esc(d.name)}:</b> ${esc(d.answer)}</div>`);log.scrollTop=log.scrollHeight;}catch{log.insertAdjacentHTML('beforeend','<div class="bubble bot">Tive um probleminha. Tente novamente.</div>')}}
document.getElementById('year').textContent=new Date().getFullYear();renderProducts();renderCart();api('/api/me').then(d=>{currentUser=d.user;if(currentUser)startHeartbeat()}).catch(()=>{});
</script>'''
s=s[:start]+script+s[end:]
p.write_text(s)
